// Level 2 — full theory for GRC professionals new to AI governance (ai05–ai08).
const P = x => ({ k: 'p', x }), H = x => ({ k: 'h', x }), U = x => ({ k: 'ul', x }), O = x => ({ k: 'ol', x });
const BR = x => ({ k: 'br', x }), AP = (s, x, t) => ({ k: 'ap', s, x, t }), V = { k: 'vis' };

export const TH2 = {
  ai05: [
    { blocks: [
      H('A product-safety law for AI'),
      P('The **EU Artificial Intelligence Act, Regulation (EU) 2024/1689**, entered into force on **1 August 2024**. It is the world’s first comprehensive AI law. Its design is borrowed from EU **product-safety legislation**: like rules for toys, machinery or medical devices, it sets requirements that AI systems must meet **before** they are placed on the market or put into service, and duties that continue **after** — monitoring, incident reporting and corrective action. The heavier the potential harm, the stricter the requirements.'),
      P('Because it is a regulation (not a directive), it applies directly in all EU Member States without national transposition, although each Member State designates its own enforcement authorities and sets penalty procedures.'),
      H('Who it covers'),
      U(['**Providers** placing AI systems or general-purpose AI models on the EU market or putting them into service in the EU — **wherever they are established**.', '**Deployers** of AI systems established or located in the EU.', '**Providers and deployers outside the EU** where the **output** produced by the AI system is **used in the EU**.', '**Importers and distributors** of AI systems, and **product manufacturers** placing AI-containing products on the market under their own name.', '**Authorised representatives** of non-EU providers.']),
      V,
      H('What is out of scope'),
      P('The Act does not apply to AI used exclusively for **military, defence or national security** purposes; to AI developed and used **solely for scientific research and development**; to **purely personal, non-professional** use; and to most **free and open-source** AI components — unless they are placed on the market as high-risk systems, fall under a prohibition, or trigger transparency duties. Research and testing before placing on the market is also largely excluded, except testing in real-world conditions.'),
      BR('Treat the AI Act like you would GDPR in a Gulf or Indian company: first decide **whether it applies** (territorial scope), then **in which role** (provider, deployer…), then **which obligations** follow from the system’s risk tier. Document each step.'),
      AP(['Determine whether the system is placed on the EU market, used by an EU-established deployer, or produces output used in the EU.', 'Check exclusions (military, research, personal use, open-source) and document why they do or do not apply.', 'Record your organisation’s role for each in-scope system.'])],
      ex: 'A Mumbai software house selling an HR screening tool to employers in Spain is a provider under the Act, even with no EU office — and it must appoint an authorised representative in the EU because the tool is high-risk.' },

    { blocks: [
      H('Risk-based regulation'),
      P('The Act sorts AI systems into tiers according to the risk their **use** poses to health, safety and fundamental rights. Obligations scale with the tier, from outright bans to no specific requirements.'),
      V,
      U(['**Unacceptable risk — prohibited** (Article 5). Practices considered incompatible with EU values, such as social scoring or emotion recognition at work.', '**High risk** (Article 6, Annexes I and III). Allowed, but subject to strict requirements before and after market placement.', '**Limited / transparency risk** (Article 50). Disclosure duties: telling people they are talking to a chatbot, marking AI-generated content, labelling deepfakes.', '**Minimal risk.** No specific obligations — spam filters, game AI, most productivity tools — though AI literacy and voluntary codes of conduct apply.']),
      P('**General-purpose AI (GPAI) models** sit alongside these tiers with their own obligations (Chapter V), and extra duties apply to GPAI models with **systemic risk**. A system can also fall into more than one category — for example, a high-risk system that also interacts with people must meet both high-risk and transparency requirements.'),
      H('Purpose, not technology, decides the tier'),
      P('This is the most important idea in the Act. Classification depends on the **intended purpose** and **context of use**, not on the type of algorithm. The same facial-analysis model may be minimal risk in a photo-editing app, a transparency case in a marketing kiosk, high-risk when used to rank job candidates, and prohibited when used to infer employees’ emotions. Assessors must therefore look at **how and where** a system is used, not just what it is.'),
      BR('It resembles data classification: the same data type can be public in one context and confidential in another. In AI Act classification, the “label” attaches to the **use case**, so the inventory must capture intended purpose precisely.'),
      AP(['Write down the intended purpose of each system in one or two precise sentences.', 'Check it against Article 5 first, then Annex I and III, then Article 50.', 'Record the resulting tier and the reasoning, citing the article or annex point.'])],
      ex: 'An emotion-detection feature is prohibited in a workplace monitoring tool but may be lawful (with transparency) in a video game — same technology, different purpose.' },

    { blocks: [
      H('Practices the EU considers unacceptable'),
      P('Article 5 lists AI practices that are **banned** in the EU because their risks to people’s rights and safety are considered too high to manage with safeguards. These prohibitions have applied since **2 February 2025**, and breaches attract the Act’s highest fines. The European Commission has published guidelines explaining each prohibition with examples.'),
      U(['**Manipulative or deceptive techniques** — subliminal, purposefully manipulative or deceptive techniques that materially distort a person’s behaviour and cause, or are likely to cause, significant harm.', '**Exploiting vulnerabilities** due to age, disability or a specific social or economic situation, to distort behaviour in a harmful way.', '**Social scoring** — evaluating or classifying people based on social behaviour or personal characteristics, leading to detrimental or disproportionate treatment in unrelated contexts.', '**Predictive policing based solely on profiling** — assessing the risk that a person will commit a crime based only on profiling or personality traits.', '**Untargeted scraping of facial images** from the internet or CCTV to create or expand facial recognition databases.', '**Emotion recognition in workplaces and education**, except for medical or safety reasons.', '**Biometric categorisation** to infer race, political opinions, trade-union membership, religious or philosophical beliefs, sex life or sexual orientation.', '**Real-time remote biometric identification in publicly accessible spaces for law enforcement**, except in narrowly defined cases with authorisation.']),
      V,
      H('New prohibitions from the Digital Omnibus'),
      P('The **Digital Omnibus on AI (Regulation (EU) 2026/1744)** adds two prohibitions applying from **2 December 2026**: AI systems that generate **non-consensual intimate imagery** (so-called “nudifier” apps) and AI that generates **child sexual abuse material**.'),
      H('Applying the bans in practice'),
      P('Prohibitions often hide inside features of otherwise acceptable products. HR and learning platforms may offer “engagement” or “sentiment” analysis from webcam video; marketing tools may use dark patterns; security products may build face databases from public sources. The assessor’s task is to look at **features**, not product names, and to check whether any feature falls within Article 5 when used in the EU.'),
      BR('Treat Article 5 like a list of **prohibited activities** in a code of conduct: it is a hard stop, not a risk to be rated. If a feature falls within it for EU use, the only acceptable treatments are to remove it, disable it for EU contexts, or redesign it so it falls outside the definition.'),
      AP(['Screen every AI system and feature against the Article 5 list before any other classification.', 'Pay special attention to emotion, sentiment, biometric and behavioural-scoring features.', 'Where a feature is prohibited in the EU, confirm in configuration that it is disabled, and obtain vendor confirmation in writing.'])],
      ex: 'An HR vendor’s “candidate enthusiasm score” from webcam facial expressions during interviews is emotion recognition in the workplace — prohibited in the EU since 2 February 2025.' },

    { blocks: [
      H('Two routes to high-risk'),
      P('Most of the Act’s requirements concern **high-risk AI systems**. Article 6 defines two routes into this category.'),
      P('**Route 1 — Annex I (products).** The AI system is itself a product, or a **safety component** of a product, covered by EU product legislation listed in Annex I that requires third-party conformity assessment — machinery, toys, lifts, radio equipment, medical devices, in vitro diagnostics, vehicles and others. An AI-based diagnostic tool that is a medical device is the classic example.'),
      P('**Route 2 — Annex III (use cases).** The AI system is intended to be used in one of eight sensitive areas:'),
      V,
      O(['**Biometrics** — remote biometric identification, biometric categorisation, emotion recognition (where not prohibited).', '**Critical infrastructure** — safety components in digital infrastructure, road traffic, water, gas, heating and electricity.', '**Education and vocational training** — admissions, evaluating learning outcomes, steering learning, proctoring.', '**Employment and worker management** — recruitment, selection, decisions on promotion and termination, task allocation, performance monitoring.', '**Access to essential private and public services** — eligibility for public benefits, **creditworthiness and credit scoring** (excluding fraud detection), **life and health insurance risk assessment and pricing**, emergency call classification and dispatch.', '**Law enforcement** — specified uses such as evidence reliability and risk assessments.', '**Migration, asylum and border control**.', '**Administration of justice and democratic processes** — assisting judicial decisions, influencing elections.']),
      H('The “no significant risk” filter'),
      P('An Annex III system is **not** high-risk if it does not pose a significant risk of harm — for example, if it performs a **narrow procedural task**, only **improves the result of a previously completed human activity**, detects decision patterns without replacing human assessment, or performs a **preparatory task**. However, an Annex III system that performs **profiling of natural persons is always high-risk**. A provider relying on this filter must **document its assessment** before placing the system on the market and register it.'),
      BR('This is a **scoping and classification decision** with legal consequences — like deciding whether a system is in PCI DSS scope. It must be documented with reasons, approved, and revisited when the use changes.'),
      AP(['Check whether the system is or is part of an Annex I product.', 'Check the intended purpose against each Annex III area.', 'If relying on the “no significant risk” filter, confirm there is no profiling and that a written assessment exists.', 'Record the classification with the specific Annex point (for example, Annex III point 4(a)).'])],
      ex: 'A CV-ranking tool is Annex III high-risk (employment, point 4). A tool that only fixes spelling in job adverts performs a narrow procedural task and is not.' },

    { blocks: [
      H('A law that applies in stages'),
      P('The Act entered into force on 1 August 2024, but its obligations apply in phases, giving organisations time to prepare. The **Digital Omnibus on AI, Regulation (EU) 2026/1744**, entered into force on **27 July 2026** and moved several deadlines — most importantly delaying high-risk obligations to allow harmonised standards and guidance to be finalised.'),
      V,
      H('Key dates (as of November 2026)'),
      U(['**2 February 2025** — prohibited practices and AI literacy (Article 4, since softened by the Omnibus to a duty to take measures supporting AI literacy).', '**2 August 2025** — obligations for GPAI model providers, governance bodies, national penalty regimes.', '**2 August 2026** — transparency obligations (Article 50) and Commission powers to fine GPAI providers.', '**2 December 2026** — the two new prohibitions; Article 50 marking for generative systems already on the market before 2 August 2026.', '**2 August 2027** — GPAI models placed on the market before 2 August 2025 must comply.', '**2 December 2027** — Annex III high-risk obligations (moved from 2 August 2026).', '**2 August 2028** — Annex I high-risk (product-embedded) obligations (moved from 2 August 2027).', '**2 August 2030** — high-risk systems used by public authorities that were already in use.']),
      H('Why dates matter for assessments'),
      P('A delay is not an exemption. Customers, investors and regulators expect organisations to be preparing; procurement questionnaires already ask about AI Act readiness; and building high-risk controls (risk management, data governance, documentation, conformity assessment) takes many months. Meanwhile prohibitions, AI literacy, GPAI rules and transparency duties already apply. Guidelines, implementing acts, codes of practice and harmonised standards also keep arriving, so assessors must always check the **latest consolidated text**.'),
      BR('Treat the timeline like a regulatory change programme: a compliance roadmap with milestones, owners and readiness evidence per obligation, tracked on your regulatory change log.'),
      AP(['For each in-scope system, list the obligations and the date each applies.', 'Check what is already in force (prohibitions, literacy, transparency) and verify compliance now.', 'Review the readiness plan for high-risk obligations ahead of December 2027 / August 2028.'])],
      ex: 'A bank that paused its AI Act project in 2026 still has to meet Article 50 transparency now and should use the extra time to finish high-risk work for its credit model before December 2027.' },

    { blocks: [
      H('Fines'),
      P('The Act sets three tiers of maximum administrative fines, each “whichever is higher” of a fixed amount and a percentage of total worldwide annual turnover:'),
      U(['**Prohibited practices** — up to **€35 million or 7%**.', '**Most other obligations**, including provider, deployer and transparency duties — up to **€15 million or 3%**.', '**Supplying incorrect, incomplete or misleading information** to authorities — up to **€7.5 million or 1%**.']),
      P('Lower caps apply to SMEs and start-ups and, after the Omnibus, to small mid-cap companies. National authorities consider factors such as the nature, gravity and duration of the infringement, cooperation and measures taken to mitigate harm.'),
      V,
      H('Who enforces'),
      P('Each Member State designates **market surveillance authorities** to enforce the rules for AI systems, and **notifying authorities** to oversee notified bodies. The **AI Office** within the European Commission supervises GPAI models and, after the Omnibus, certain AI systems built on GPAI models by the same provider. The **European AI Board** coordinates Member States, supported by an advisory forum and a scientific panel of independent experts.'),
      H('AI literacy (Article 4)'),
      P('Providers and deployers must take measures to support a **sufficient level of AI literacy** among staff and others operating or using AI systems on their behalf, taking into account their technical knowledge, experience, education and the context of use. In practice this means role-based training: general awareness for all staff, practical guidance for AI users, deeper training for developers, reviewers and approvers — with records of who completed what.'),
      BR('AI literacy is a **competence and awareness control** — like security awareness training under ISO 27001 clause 7. Expect auditors to ask for the training programme, role mapping and completion records.'),
      AP(['Confirm the organisation knows which fine tier applies to each obligation for its in-scope systems.', 'Check an AI literacy programme exists with role-based content and completion records.', 'Identify the relevant market surveillance authorities for the Member States where systems are used.'])],
      ex: 'An AI literacy programme with role-based modules (general staff, AI users, developers, approvers) plus completion records is the expected evidence — this academy itself can form part of such a programme.' }
  ],

  ai06: [
    { blocks: [
      H('What “high-risk” requires'),
      P('If a system is high-risk, the provider must ensure it meets seven requirements set out in **Articles 9 to 15** before it is placed on the market, and keep meeting them throughout its life. These requirements are the technical heart of the Act and the area where assessors will spend most time.'),
      V,
      U(['**Article 9 — Risk management system.** A continuous, iterative process across the lifecycle: identify and analyse known and foreseeable risks to health, safety and fundamental rights, including reasonably foreseeable misuse; adopt risk management measures; test to ensure residual risk is acceptable.', '**Article 10 — Data and data governance.** Training, validation and testing data must be relevant, sufficiently representative and, to the best extent possible, free of errors and complete for the intended purpose; examine possible biases and take measures to detect, prevent and mitigate them; document data collection, preparation and assumptions.', '**Article 11 — Technical documentation.** Prepared before market placement and kept up to date, with the contents listed in Annex IV: system description, design, development process, data, testing, performance, risk management, changes.', '**Article 12 — Record-keeping.** The system must automatically record events (logs) to allow traceability of its functioning throughout its life.', '**Article 13 — Transparency and instructions for use.** Deployers must receive clear instructions covering intended purpose, accuracy, limitations, human-oversight measures and how to interpret outputs.', '**Article 14 — Human oversight.** The system must be designed so that natural persons can effectively oversee it: understand its capacities and limits, remain aware of automation bias, interpret outputs, decide not to use or to override them, and intervene or stop the system.', '**Article 15 — Accuracy, robustness and cybersecurity.** Appropriate levels declared in the instructions, resilience to errors and inconsistencies, and protection against attacks such as data poisoning and adversarial examples.']),
      BR('These seven requirements map closely to controls in ISO/IEC 42001 Annex A (risk and impact assessment, data controls, documentation, logging, information for users, human oversight, verification and validation). Many organisations therefore use 42001 as their **implementation backbone** and evidence base for the Act.'),
      AP(['For a high-risk system, create a seven-row evidence matrix (Articles 9–15) and request evidence for each.', 'For Article 10, check representativeness analysis and bias examination results.', 'For Article 14, verify oversight is designed into the system and reflected in instructions for use.'])],
      ex: 'For a credit model, Article 10 evidence includes the datasheet describing data sources and period, a representativeness analysis comparing training data with the applicant population, and bias test results by relevant groups.' },

    { blocks: [
      H('Beyond the seven requirements'),
      P('Providers of high-risk systems carry further obligations that turn the requirements into a controlled, auditable process for placing a product on the market:'),
      U(['**Quality management system** (Article 17) — documented policies and procedures covering design, development, testing, data management, risk management, post-market monitoring, incident reporting, communication with authorities and accountability.', '**Documentation and logs** (Articles 18–19) — keep documentation for ten years and logs under the provider’s control for an appropriate period.', '**Conformity assessment** (Article 43) — before placing on the market. For most Annex III systems this is **internal control** (self-assessment against the requirements); for certain biometric systems and for Annex I products, a **notified body** is involved under the relevant procedure.', '**EU declaration of conformity and CE marking** (Articles 47–48).', '**Registration in the EU database** (Article 49) for Annex III systems.', '**Post-market monitoring** (Article 72) — actively collect and analyse data on performance throughout the system’s life.', '**Serious incident reporting** (Article 73) — report to market surveillance authorities within set deadlines.', '**Corrective action and cooperation** with authorities when a system is non-compliant.']),
      V,
      H('Substantial modification'),
      P('If a high-risk system undergoes a **substantial modification** after it has been placed on the market — a change not foreseen in the original conformity assessment that affects compliance or modifies the intended purpose — a **new conformity assessment** is required. Models that keep learning after deployment can avoid this only if the changes were pre-determined and documented in the original assessment.'),
      BR('This is very close to ISO-style product certification and to change control in regulated environments (for example, validated systems in pharma). Expect version control, change impact assessments and re-approval for significant changes.'),
      AP(['Ask the provider (or vendor) for the QMS documentation, the conformity assessment record and the EU declaration of conformity.', 'Check the system’s EU database registration for Annex III systems.', 'Review how changes are assessed for “substantial modification”.', 'Check that post-market monitoring and incident reporting procedures exist and have been exercised.'])],
      ex: 'A provider retraining its high-risk model in a way not foreseen in the original documentation must reassess conformity before releasing the new version — otherwise the new version is on the market without a valid assessment.' },

    { blocks: [
      H('Deployers have their own duties'),
      P('Most organisations will be **deployers** of high-risk systems bought from vendors — HR platforms, credit-scoring services, insurance pricing tools. Article 26 sets their obligations, which are lighter than providers’ but very real:'),
      U(['Use the system **in accordance with the instructions for use**.', 'Assign **human oversight** to people with the necessary competence, training, authority and support.', 'Ensure **input data** under their control is relevant and sufficiently representative for the intended purpose.', '**Monitor** the system’s operation and inform the provider and authorities of risks or serious incidents; suspend use if necessary.', 'Keep automatically generated **logs** under their control for **at least six months** (unless other law requires otherwise).', '**Inform workers and their representatives** before putting a high-risk system into use at the workplace.', '**Inform natural persons** that they are subject to the use of a high-risk system that makes or assists decisions about them.', 'Use the provider’s information to carry out a **data protection impact assessment** where required.']),
      V,
      H('The Fundamental Rights Impact Assessment (FRIA)'),
      P('Article 27 requires certain deployers to carry out a **FRIA** before first use: **bodies governed by public law**, **private entities providing public services**, and deployers using high-risk systems for **creditworthiness assessment / credit scoring** or **risk assessment and pricing in life and health insurance**. The FRIA describes the process in which the system is used, the period and frequency of use, the categories of people affected, the specific risks of harm to them, the human-oversight measures, and the measures to take if risks materialise, including governance and complaint mechanisms. The deployer notifies the market surveillance authority of the results, and can build on an existing DPIA.'),
      H('The right to an explanation'),
      P('Under Article 86, a person affected by a decision taken on the basis of a high-risk system’s output, which produces legal effects or similarly significantly affects them, has the right to obtain **clear and meaningful explanations** of the role of the AI system in the decision and the main elements of the decision.'),
      BR('Deployer obligations resemble your duties when using a critical outsourced service: use it as designed, monitor it, keep records, tell affected people, and escalate problems to the supplier. The FRIA is the AI-specific addition, best run together with the DPIA.'),
      AP(['Check that instructions for use were obtained and are followed in practice.', 'Verify named, trained reviewers and evidence of oversight activity.', 'Confirm log retention of at least six months.', 'Check worker and individual notices.', 'Determine whether a FRIA is required, and if so that it exists and was notified.'])],
      ex: 'An insurer in Ireland using an AI pricing model for health insurance must complete a FRIA before first use and notify the market surveillance authority of its results.' },

    { blocks: [
      H('Why transparency obligations exist'),
      P('Even when an AI system is not high-risk, people have an interest in knowing when they are dealing with a machine or looking at machine-made content. Article 50 sets **transparency obligations** for specific types of system, regardless of risk tier. They apply from **2 August 2026**.'),
      V,
      H('The obligations'),
      U(['**Interactive AI (chatbots, voice assistants)** — providers must design systems so that people are informed they are interacting with AI, unless this is obvious from the circumstances.', '**Synthetic content** — providers of generative AI systems must ensure outputs (audio, image, video, text) are **marked in a machine-readable format** and detectable as artificially generated, as far as technically feasible.', '**Emotion recognition and biometric categorisation** — deployers must inform the people exposed (where such use is lawful).', '**Deepfakes** — deployers must disclose that image, audio or video content resembling real people, objects, places or events has been artificially generated or manipulated. Lighter rules apply to evidently artistic, creative, satirical or fictional work.', '**AI-generated text published to inform the public on matters of public interest** — deployers must disclose that it is AI-generated, unless it has undergone human review or editorial control with editorial responsibility.']),
      P('Generative systems already on the market before 2 August 2026 had until **2 December 2026** to implement marking. A Commission-facilitated **Code of Practice on marking and labelling** supports implementation.'),
      BR('These are disclosure controls — similar to cookie banners or privacy notices. Test them the same way: inspect the user interface, sample content, and check that marking survives the publishing workflow.'),
      AP(['Inventory every chatbot, voice assistant and generative-content use.', 'Check disclosures appear at the start of AI interactions.', 'For generated media, check machine-readable marking and visible labels where required.', 'Review marketing and communications processes for deepfake disclosure.'])],
      ex: 'A marketing team using AI to create a realistic video of a “customer testimonial” must label it as AI-generated — and should question whether the video is deceptive at all under consumer protection law.' },

    { blocks: [
      H('Regulating the models underneath'),
      P('Many AI systems are built on **general-purpose AI (GPAI) models** — large models such as LLMs that can perform many tasks and be integrated into many systems. The Act regulates the **providers of these models** separately (Chapter V), because problems in a widely used model propagate to every system built on it.'),
      H('Obligations for all GPAI model providers (Article 53)'),
      U(['Draw up and maintain **technical documentation** of the model, including training and testing, for the AI Office and national authorities.', 'Provide **information and documentation to downstream providers** who integrate the model, so they understand capabilities and limitations and can meet their own obligations.', 'Put in place a **policy to comply with EU copyright law**, including respecting text-and-data-mining opt-outs.', 'Publish a **sufficiently detailed summary of the content used for training**, using the Commission’s template.']),
      P('Providers of free and open-source models are exempt from some documentation duties unless the model has systemic risk.'),
      V,
      H('GPAI models with systemic risk (Article 55)'),
      P('A GPAI model is presumed to have **systemic risk** when the cumulative compute used for its training exceeds **10^25 floating-point operations**, or when designated by the Commission based on its capabilities or reach. Such providers must additionally perform **model evaluations including adversarial testing**, **assess and mitigate systemic risks**, **track and report serious incidents** to the AI Office, and ensure **adequate cybersecurity** for the model and its infrastructure.'),
      H('The GPAI Code of Practice'),
      P('The **General-Purpose AI Code of Practice**, published in July 2025, has chapters on transparency, copyright and safety and security. Signing and following it is a recognised way to demonstrate compliance. GPAI obligations apply since **2 August 2025**; models already on the market before then have until **2 August 2027**.'),
      BR('For most organisations, GPAI rules are a **supply-chain** matter: you are not the model provider, but you depend on the information they must supply. Include GPAI documentation, copyright policy and Code of Practice status in vendor due diligence.'),
      AP(['Identify the GPAI models underlying your AI systems and their providers.', 'Request the downstream documentation (model or system cards) and assess limitations relevant to your use.', 'Check whether the provider has signed the GPAI Code of Practice.', 'If your organisation substantially fine-tunes and releases a model, check whether you become a GPAI provider.'])],
      ex: 'A company that only builds an app on top of a provider’s API is not a GPAI model provider — but it is the provider of its own AI system and relies on the model provider’s downstream information to meet its obligations.' },

    { blocks: [
      H('The situation'),
      P('A Bengaluru HR-tech firm sells a CV screening and interview-scheduling platform to European employers. Its sales team reports that EU clients are asking about “AI Act compliance” in tenders. The firm’s risk manager, experienced in ISO 27001 and SOC 2, is asked to lead the response.'),
      H('Step 1 — Classify'),
      P('CV screening and candidate ranking are used for recruitment and selection — **Annex III point 4** (employment) — so the screening component is **high-risk**. Interview scheduling alone is a narrow procedural task and would not be. The firm places the system on the EU market under its own name, so it is the **provider**; each employer is a **deployer**.'),
      V,
      H('Step 2 — Provider obligations'),
      U(['Risk management system (Art. 9), including foreseeable misuse such as using scores as the sole basis for rejection.', 'Data governance (Art. 10): bias testing on data representative of EU applicant populations, not only Indian data.', 'Annex IV technical documentation, automatic logging, clear instructions for use, human-oversight features (reviewers can see reasons and override), declared accuracy and robustness.', 'Quality management system, conformity assessment (internal control), EU declaration of conformity, CE marking, EU database registration, post-market monitoring and incident reporting.', 'Appoint an **authorised representative in the EU**, as required for non-EU providers of high-risk systems.']),
      H('Step 3 — Support deployers'),
      P('Employers must use the system per instructions, assign trained reviewers, inform candidates and works councils, keep logs for at least six months and handle explanation requests. The provider makes this easy through product features (log export, reason codes, candidate notice templates) and documentation.'),
      H('Step 4 — Plan the timeline'),
      P('Annex III obligations apply from **2 December 2027**, but clients demand evidence now. The firm builds a readiness roadmap with quarterly milestones and shares progress in tenders. It also reviews features against Article 5 and drops a planned “personality from video” feature, which would amount to emotion recognition in a workplace context — prohibited.'),
      BR('The risk manager reuses existing ISMS processes — document control, change management, supplier management, internal audit — and adds AI-specific controls. Pursuing ISO/IEC 42001 certification gives a structured backbone and a credible signal to clients.'),
      AP(['Classify each component of a product separately.', 'Build a provider obligation checklist and a deployer-support pack.', 'Screen all features against Article 5.', 'Create a dated readiness roadmap and evidence log.'])],
      ex: 'The firm drops a planned “personality from video” feature after realising it would be emotion recognition in the workplace — prohibited — and turns its compliance work into a selling point in EU tenders.' }
  ],

  ai07: [
    { blocks: [
      H('A practical method for AI risk'),
      P('The **NIST AI Risk Management Framework (AI RMF 1.0, NIST AI 100-1)**, released by the US National Institute of Standards and Technology in January 2023, is a **voluntary**, sector-agnostic framework for managing AI risk. It is not a law and not a certifiable standard, but it is widely used worldwide — including in the Gulf and India — because it is practical, free and well supported. NIST has announced a revision of the framework; check the NIST site for the current version.'),
      H('Structure'),
      P('**Part 1** explains how to frame AI risk: the types of harm (to people, organisations and ecosystems), challenges such as measuring risk and deciding risk tolerance, and the **seven characteristics of trustworthy AI**. **Part 2**, the **Core**, organises activities into four functions — **GOVERN, MAP, MEASURE, MANAGE** — each broken into categories and subcategories describing outcomes. A companion **Playbook** suggests concrete actions and documentation for every subcategory.'),
      V,
      P('The functions are not strictly sequential. GOVERN applies throughout; MAP, MEASURE and MANAGE are repeated across the lifecycle as systems change.'),
      H('How it fits with other frameworks'),
      P('The AI RMF is often combined with ISO/IEC 42001: the AI RMF provides the detailed **“how”** of risk work, while 42001 provides the certifiable **management system** around it. NIST has also published crosswalks to ISO/IEC standards and other frameworks, and its trustworthy characteristics align with OECD principles and EU AI Act requirements.'),
      BR('If you know the NIST Cybersecurity Framework (Identify, Protect, Detect, Respond, Recover), the AI RMF will feel familiar: functions, categories, subcategories and profiles. The difference is that the outcomes cover **fairness, explainability, privacy and societal impact**, not only security.'),
      AP(['Use the four functions as the structure for an AI governance maturity review.', 'Use Playbook suggested actions as a source of control ideas and evidence requests.'])],
      ex: 'Many organisations use the AI RMF as the “how” and ISO/IEC 42001 as the certifiable “management system” around it — the two are complementary rather than competing.' },

    { blocks: [
      H('GOVERN: the foundation'),
      P('**GOVERN** is described as **cross-cutting**: it informs and is applied across the other three functions. It is about the organisational conditions that make AI risk management possible — policies, accountability, culture and resources. Without GOVERN, the other functions become isolated technical exercises that depend on individual goodwill.'),
      V,
      H('What GOVERN covers'),
      U(['**Policies, processes and procedures** for mapping, measuring and managing AI risk, aligned with legal and regulatory requirements and the organisation’s risk tolerance.', '**Accountability structures** — clear roles, responsibilities and lines of authority; training; and senior leadership responsibility for AI risk decisions.', '**Workforce diversity, equity, inclusion and accessibility** in the teams making AI decisions, to bring different perspectives to risk identification.', '**A culture** that considers and communicates AI risk, including mechanisms for staff to raise concerns.', '**Engagement with external stakeholders** and affected communities, and integration of their feedback.', '**Policies for third-party software, data and models**, including risks from the AI supply chain.']),
      H('What good looks like'),
      P('In a mature organisation you would find an approved AI policy, an AI governance committee or equivalent with a charter, a RACI for AI decisions, role-based training records, a process for raising and handling AI concerns, inventory and intake procedures, and third-party AI requirements built into procurement.'),
      BR('GOVERN corresponds to the **leadership, policy, roles and competence** clauses of ISO management systems and to the “tone at the top” you assess in any control environment review.'),
      AP(['Request the AI policy, committee charter and minutes, RACI and training records.', 'Check how staff raise AI concerns and whether any were raised and handled.', 'Check third-party AI requirements in procurement.'])],
      ex: 'GOVERN evidence: an approved AI policy, a RACI for AI decisions, mandatory training records and an AI risk committee charter with minutes showing real decisions.' },

    { blocks: [
      H('MAP: understand before you judge'),
      P('**MAP** establishes the **context** needed to identify risks. You cannot judge whether an AI system is risky without understanding what it is for, who uses it, who is affected and in what setting. MAP is where many poor use cases should be stopped or narrowed — before money is spent.'),
      V,
      H('What MAP covers'),
      U(['**Intended purpose, users and deployment setting**, including expected benefits and the legal and regulatory context.', '**Categorisation** of the AI system and the tasks it performs (classification, generation, recommendation).', '**Capabilities, limitations and assumptions** — including what the system should **not** be used for, and the knowledge limits of the people operating it.', '**Risks and benefits for all components**, including third-party data, models and software.', '**Impacts on individuals, groups, communities, organisations and society**, both positive and negative, including likelihood and magnitude.']),
      H('Doing MAP well'),
      P('Good mapping involves the right people: business owners, technical teams, legal, privacy, risk, and — where possible — representatives of affected people. It considers not only intended use but **reasonably foreseeable misuse**. Its outputs feed the impact assessment and determine what needs to be measured.'),
      BR('MAP is the **context establishment** step of ISO 31000 risk management — scope, context and criteria — applied to an individual AI system. Many organisations implement it through an AI **intake questionnaire**.'),
      AP(['Check that each assessed system has a documented purpose, user groups, affected people and out-of-scope uses.', 'Check that third-party components are identified.', 'Look for evidence that a use case was narrowed or stopped as a result of mapping — a sign the step is real.'])],
      ex: 'Mapping a tenant-screening model reveals it would affect housing access for migrant workers with thin credit files — a key impact that now must be measured before approval.' },

    { blocks: [
      H('MEASURE: evidence about risk'),
      P('**MEASURE** uses quantitative and qualitative methods to **analyse, assess, benchmark and monitor** AI risks and impacts identified in MAP. It includes testing on representative data; fairness metrics; robustness and security testing; red-teaming; evaluation of explainability; privacy testing; collecting user and affected-community feedback; and tracking metrics over time in production.'),
      P('An important and often overlooked idea is **measuring the measurement**: are the metrics valid for the risk in question? Is the test data representative? Are there risks that are hard to measure and therefore need qualitative judgement? MEASURE also expects independent review of test results where appropriate.'),
      V,
      H('MANAGE: decide and act'),
      P('**MANAGE** allocates resources to treat the risks mapped and measured. It covers prioritising risks; deciding whether the system should proceed; selecting treatments (mitigate, transfer, avoid, accept); documenting residual risk; planning responses to incidents and recovery; managing third-party risks; and monitoring after deployment. It explicitly includes mechanisms to **supersede, disengage or deactivate** AI systems that perform inconsistently with intended use.'),
      BR('MEASURE corresponds to risk analysis and control testing; MANAGE to risk treatment, incident response and business continuity. The AI-specific elements are **model testing methods** and the **ability to switch off or roll back** a model safely.'),
      AP(['Ask for the test plan and results, including fairness and robustness, and how metrics were chosen.', 'Check that residual risks are documented and accepted by an appropriate owner.', 'Verify an incident playbook and a tested deactivation (“kill switch”) procedure exist.'])],
      ex: 'MANAGE evidence: a risk treatment plan with owners and dates, an AI incident playbook, and a documented and tested procedure to switch the model off and fall back to manual processing.' },

    { blocks: [
      H('Applying the framework to generative AI'),
      P('In **July 2024** NIST published the **Generative AI Profile (NIST AI 600-1)**, which applies the AI RMF to generative AI. It identifies **twelve risks** that are unique to or worsened by GenAI, and suggests actions mapped to AI RMF subcategories.'),
      V,
      H('The twelve risks explained'),
      U(['**CBRN information or capabilities** — easier access to information that could help create chemical, biological, radiological or nuclear weapons.', '**Confabulation** — confident but false or unsupported outputs.', '**Dangerous, violent or hateful content**.', '**Data privacy** — leakage of personal data, inference of sensitive information.', '**Environmental impacts** — energy and resource use.', '**Harmful bias and homogenisation** — biased outputs and reduced diversity of content and opinions.', '**Human–AI configuration** — over-reliance, automation bias, anthropomorphism (treating the system as a person).', '**Information integrity** — misinformation, disinformation and deepfakes.', '**Information security** — attacks on GenAI systems (prompt injection, data poisoning) and use of GenAI for attacks.', '**Intellectual property** — infringement through training data or outputs.', '**Obscene, degrading and/or abusive content**.', '**Value chain and component integration** — risks from third-party models, data and components that are hard to verify.']),
      H('Using the profile'),
      P('Not every risk applies to every use case. A practical approach is to select the risks relevant to the use, then pick suggested actions such as content provenance, pre-deployment testing and red-teaming, monitoring, and incident disclosure. For many business applications, confabulation, data privacy, information security, intellectual property and human–AI configuration are the priorities.'),
      BR('Use the twelve risks as a **risk catalogue** — a standard list of risk scenarios to consider in every GenAI assessment, like a threat catalogue in security risk assessment.'),
      AP(['For each GenAI system, rate each of the twelve risks as relevant or not, with reasons.', 'For relevant risks, record controls and test evidence.'])],
      ex: 'A legal-research assistant prioritises confabulation, intellectual property and data privacy, and tests every citation against a verified case database before release.' },

    { blocks: [
      H('What a profile is'),
      P('An **AI RMF profile** is an organisation’s own implementation of the framework: it selects the categories and subcategories relevant to its sector, risk appetite and resources, sets **target outcomes**, and compares the **current state** with the target. The gap becomes a prioritised roadmap. NIST encourages sector and use-case profiles; the Generative AI Profile is one example.'),
      H('The situation'),
      P('A Dubai bank has around 40 AI use cases — credit scoring, fraud detection, chatbots, marketing models, AML alert prioritisation — and no consistent way to assess them. The Chief Risk Officer asks for a light, practical method that will satisfy CBUAE expectations and later support ISO/IEC 42001 certification.'),
      V,
      H('The profile the bank built'),
      U(['**GOVERN** — board-approved AI policy; AI risk committee reporting to the board risk committee; a defined “model owner” role; AI literacy training by role.', '**MAP** — a mandatory intake questionnaire for every use case: purpose, data, affected customers, jurisdictions (onshore, DIFC), CBUAE and consumer-protection obligations, third parties.', '**MEASURE** — a standard test pack scaled by tier: accuracy and stability, fairness by nationality, gender and age, explainability for customer-facing decisions, security checks for GenAI.', '**MANAGE** — risk tiering decides the approval level; high-tier models need committee sign-off, quarterly monitoring and an annual independent validation; an incident playbook and kill-switch procedure for every customer-facing system.']),
      P('A current-versus-target assessment showed the biggest gaps in inventory completeness, fairness testing and monitoring. These became a funded 12-month roadmap. Because each control was mapped to ISO/IEC 42001 clauses and Annex A, the bank later used the same evidence for certification readiness.'),
      BR('This is exactly how organisations adopt the NIST CSF: build a target profile, assess the current profile, prioritise the gap. The same programme-management discipline applies.'),
      AP(['Select relevant subcategories, define target outcomes per risk tier, and assess current state.', 'Turn gaps into a roadmap with owners, budget and dates.', 'Map each control to ISO/IEC 42001 and applicable regulations to reuse evidence.'])],
      ex: 'Current-versus-target gap analysis turns the framework into a funded roadmap rather than a reading exercise.' }
  ],

  ai08: [
    { blocks: [
      H('The core tension'),
      P('Data protection laws around the world share a common set of principles, from the OECD privacy guidelines through GDPR to the UAE PDPL and India’s DPDP Act. These principles were designed to limit how much personal data is collected and how it is used. AI, especially machine learning, tends to want **more data, reused in new ways, kept for longer**. Managing this tension is one of the central tasks in any AI assessment involving people.'),
      V,
      H('Principle by principle'),
      U(['**Lawfulness and transparency** — a valid lawful basis and clear notice. Hard when data collected for one purpose is later reused to train a model, and when model logic is complex.', '**Purpose limitation** — data collected for one purpose cannot freely be reused for an incompatible one (for example, customer-service chats reused to train a sales-targeting model).', '**Data minimisation** — use only what is necessary. Models often perform better with more features and more history, so minimisation needs deliberate decisions.', '**Accuracy** — applies to the data and to **inferences** about people. A model’s prediction that someone is a fraud risk is personal data that must be accurate enough for its use.', '**Storage limitation** — retention periods for training datasets, feature stores, prompts and logs.', '**Security** — including AI-specific threats such as model inversion and memorisation leaks.', '**Accountability** — being able to demonstrate compliance through documentation.']),
      BR('You already assess these principles in privacy reviews. For AI, add three questions: **is training a new purpose? are inferences accurate and fair? can the model leak or reveal personal data?**'),
      AP(['Identify all personal data used for training, at run time and in logs.', 'Check whether training is compatible with the original collection purpose and notice.', 'Check minimisation decisions (features removed, data period limited) are documented.', 'Check retention periods for training data, prompts and logs.'])],
      ex: 'Before reusing three years of call recordings to train a speech model, check the original notice, the lawful basis for the new purpose, retention limits, and whether de-identification is feasible.' },

    { blocks: [
      H('Why GDPR still matters to Gulf and Indian organisations'),
      P('GDPR applies to organisations outside the EU that offer goods or services to people in the EU or monitor their behaviour. It also shapes the design of many other laws, including the DIFC and ADGM regimes. Understanding how GDPR applies to AI is therefore useful far beyond Europe.'),
      H('Key GDPR provisions for AI'),
      U(['**Lawful basis (Article 6)** — training often relies on **legitimate interests**, which requires a documented balancing test showing the organisation’s interest is not overridden by individuals’ rights. Consent is needed where other bases do not apply.', '**Special category data (Article 9)** — health, biometrics, ethnicity, religion and similar data need an Article 9 condition. The AI Act (as amended by the Omnibus) adds a narrow basis to process such data for **bias detection and correction** under strict safeguards.', '**Automated decisions (Article 22)** — individuals have a right not to be subject to decisions based **solely** on automated processing that produce legal or similarly significant effects, subject to exceptions (contract necessity, law, explicit consent) and safeguards including the right to human intervention, to express their view and to contest.', '**DPIA (Article 35)** — required for processing likely to result in high risk; most impactful AI uses qualify.', '**Data subject rights** — access, rectification, erasure and objection are hard to honour once data has been used to train a model, and require planning.']),
      V,
      H('Guidance and case law'),
      P('The European Data Protection Board’s **Opinion 28/2024** (December 2024) concluded that AI models trained on personal data are **not automatically anonymous**: anonymity must be demonstrated case by case, considering the likelihood of extracting personal data. It also explained how legitimate interests may be used and that unlawful training can affect the lawfulness of later use of the model. In the **SCHUFA** judgment (2023), the Court of Justice of the EU found that a credit score can itself be an automated decision under Article 22 when lenders rely on it decisively.'),
      BR('Article 22 is effectively a **control requirement**: meaningful human involvement or specific safeguards. Test it like any control — is the human review real, documented and able to change the outcome?'),
      AP(['Check the lawful basis and balancing test for training and for operational use.', 'Check whether decisions are solely automated with significant effects; if so, check Article 22 safeguards.', 'Confirm a DPIA covers the AI use.', 'Ask how erasure and objection requests are handled for data already used in training.'])],
      ex: 'A CJEU judgment in 2023 (SCHUFA) found that a credit score can itself be an automated decision under Article 22 when lenders rely on it decisively — so the score provider, not only the lender, must consider the safeguards.' },

    { blocks: [
      H('Three regimes in one country'),
      P('The UAE does not have a single data protection law for the whole country. An assessor must first establish **where** the organisation and processing sit.'),
      V,
      H('Onshore: the PDPL'),
      P('The **UAE Personal Data Protection Law, Federal Decree-Law No. 45 of 2021**, effective 2 January 2022, applies onshore. It sets lawful grounds including consent, requires notice, grants data subject rights — including the **right to object to decisions based solely on automated processing** that produce legal consequences or seriously affect the individual — requires breach notification to the **UAE Data Office**, and regulates cross-border transfers. The status of its **executive regulations**, which set many operational details, should always be checked. The PDPL does **not** apply in free zones that have their own data protection law, nor to **health and banking data** governed by their own sector legislation.'),
      H('DIFC: Data Protection Law and Regulation 10'),
      P('In the Dubai International Financial Centre, **Data Protection Law No. 5 of 2020** applies, closely modelled on GDPR. **Regulation 10** adds specific requirements for personal data processed through **autonomous and semi-autonomous systems**: clear notice at first use describing the system and its purpose; purposes defined by humans; design principles such as fairness, transparency, security and accountability; algorithms that trigger human intervention where outcomes may be unfair or discriminatory; records in an AI register; and an **Autonomous Systems Officer** for certain high-risk processing.'),
      H('ADGM: Data Protection Regulations 2021'),
      P('In Abu Dhabi Global Market, the **Data Protection Regulations 2021** apply, also closely modelled on GDPR, overseen by the ADGM Office of Data Protection.'),
      BR('Treat UAE data protection like a multi-entity group: map each legal entity and processing activity to its regime first, then apply that regime’s requirements. Mis-identifying the regime is a common and serious error.'),
      AP(['Determine whether processing is onshore, in DIFC, in ADGM or under a sector law (health, banking).', 'For DIFC autonomous systems, check Regulation 10 notice, human-defined purpose, intervention triggers, register and ASO where required.', 'For onshore automated decisions, check how the right to object is honoured.'])],
      ex: 'A DIFC-based wealth manager deploying an AI portfolio assistant must meet the DIFC DP Law and Regulation 10 — not the onshore PDPL.' },

    { blocks: [
      H('India’s Digital Personal Data Protection framework'),
      P('India’s **Digital Personal Data Protection Act, 2023** governs digital personal data, including data collected offline and later digitised. It applies to processing in India and to processing outside India connected with offering goods or services to people in India. The **DPDP Rules, 2025** were notified on **13 November 2025** with a phased rollout.'),
      V,
      H('Timeline'),
      U(['**13 November 2025** — Data Protection Board established; framework provisions in force.', '**November 2026 (12 months)** — consent manager registration and obligations.', '**13 May 2027 (18 months)** — core duties: notice and consent, data principal rights, children’s data, security safeguards, breach notification, retention and erasure, Significant Data Fiduciary obligations.']),
      H('What matters for AI'),
      U(['**Consent** must be free, specific, informed, unconditional and unambiguous, given through a clear affirmative action, and limited to data necessary for the specified purpose. Notice must itemise the data and purpose and can be given in English or any language in the Eighth Schedule of the Constitution.', '**Legitimate uses** allow processing without consent in limited situations specified in the Act.', '**Publicly available data** made available by the data principal themselves is outside the Act’s scope — relevant to debates about scraping for AI training.', '**No GDPR-style Article 22** right concerning automated decisions; fairness protections come instead from sector regulators and other laws.', '**Children’s data** requires verifiable parental consent; tracking, behavioural monitoring and targeted advertising directed at children are restricted.', '**Significant Data Fiduciaries** designated by the government must appoint a Data Protection Officer in India, run periodic DPIAs and audits, and verify that algorithmic software they use does not pose risks to data principals’ rights.', '**Penalties** reach up to **₹250 crore** per instance for the most serious failures, such as failing to take reasonable security safeguards.']),
      BR('The DPDP Act is **consent-centred** and more prescriptive about notice and consent mechanics than GDPR, but lighter on automated-decision rights. When assessing AI for Indian users, focus on consent quality, purpose limitation, children and security.'),
      AP(['Check that notices itemise data used for AI and are available in users’ languages.', 'Confirm consent is specific to AI-related purposes where consent is the basis.', 'Check children’s data handling.', 'Plan readiness for 13 May 2027 obligations now.'])],
      ex: 'An Indian edtech using student data to personalise learning must plan for verifiable parental consent for under-18 users by May 2027, and should avoid behavioural tracking aimed at children.' },

    { blocks: [
      H('Reducing privacy risk with technology'),
      P('**Privacy-enhancing technologies (PETs)** help organisations use data for AI while reducing risk to individuals. None makes data risk-free, and each has limitations an assessor should understand.'),
      V,
      U(['**De-identification and pseudonymisation** — removing or replacing direct identifiers. Pseudonymised data is still personal data; true anonymisation is hard because combinations of attributes can re-identify people.', '**Synthetic data** — artificially generated data that mimics the statistical properties of real data. Useful for testing and sharing, but must be checked to ensure it does not reproduce real individuals’ records.', '**Differential privacy** — adds calibrated statistical noise so that results reveal little about any single individual; there is a trade-off between privacy and accuracy.', '**Federated learning** — trains a model across devices or sites without centralising raw data; model updates can still leak information and need protection.', '**Secure enclaves and encryption in use** — protect data while it is being processed.']),
      H('Organisational controls'),
      P('Technology works only alongside process controls: **access controls** on training data and feature stores; **data lineage** showing where data came from and which models used it; **retention rules for prompts and logs**, which often contain personal data; and **testing for memorisation and leakage** before releasing models trained on personal data.'),
      H('One assessment, not two'),
      P('Rather than running a DPIA and an AI impact assessment separately, mature organisations combine them into one workflow, so privacy and broader AI risks (fairness, safety, transparency) are assessed together and controls are not duplicated.'),
      BR('PETs are technical controls; evaluate them like encryption or tokenisation: **what threat do they address, what residual risk remains, and is there evidence they were implemented correctly?**'),
      AP(['Ask which PETs are used and what residual re-identification risk was assessed.', 'Check retention settings for prompts and logs.', 'Check whether memorisation testing was done for models trained on personal data.', 'Check whether the DPIA and AI impact assessment are integrated.'])],
      ex: 'A hospital group shares a model, not patient records, across sites using federated learning, plus a joint DPIA covering all sites.' },

    { blocks: [
      H('The situation'),
      P('A telecom operator with customers in the UAE and India wants to fine-tune an LLM on **two million customer-service chats** so its virtual assistant can answer more accurately. The privacy team, experienced with GDPR-style programmes, is asked to approve the project.'),
      H('Step-by-step assessment'),
      O(['**Map the law.** UAE onshore customers → PDPL. Indian customers → DPDP Act (core duties from May 2027, but design now). Any EU roaming customers whose data is included → possibly GDPR.', '**Purpose and notice.** Were customers told their chats could be used to improve services with AI? If not, update notices and assess compatibility of the new purpose, or obtain consent where required.', '**Minimise.** Strip names, phone numbers, account IDs, addresses and payment details; exclude chats about sensitive topics (health, complaints involving minors).', '**Assess.** Run a joint DPIA and AI impact assessment covering leakage, bias across languages and dialects, and accuracy.', '**Test.** Before release, test the fine-tuned model for **memorisation** — can it be prompted to reproduce personal data from training chats?', '**Rights.** Define how objections and deletion requests are handled, including filtering or retraining.', '**Contracts.** If a vendor performs fine-tuning, ensure data is not reused to train the vendor’s general models and is deleted after the project; confirm hosting regions.']),
      V,
      H('The decision'),
      P('The operator decides to train only on chats from the last 12 months collected after a notice update, de-identified, with Arabic, English and Hindi coverage checked, and with a memorisation test and red-team review before release. The DPIA records residual risks and is approved by the DPO and the business owner.'),
      BR('This is a standard privacy-by-design review. The AI-specific additions are **memorisation testing**, **language-coverage checks** and **vendor terms on model training**.'),
      AP(['Use this seven-step sequence for any project that trains or fine-tunes on personal data.', 'Insist on memorisation testing evidence before release.'], '', 'Checklist: training AI on personal data')],
      ex: 'The operator decides to train only on chats from the last 12 months collected after a notice update, de-identified, with a memorisation test before release — a lawful, defensible version of the original idea.' }
  ]
};
